import React, { useState, useEffect, useRef } from 'react';
import '../components/OutTheMusic.css';

// Importar todas las imágenes disponibles
import a1 from '../assets/images/a1.png';
import a2 from '../assets/images/a2.png';
import disc1 from '../assets/images/disc1.jpg';
import disc2 from '../assets/images/disc2.webp';
import disc3 from '../assets/images/disc3.webp';
import disc4 from '../assets/images/disc4.jpg';
import logoNeto from '../assets/images/logo_neto.png';
import ytLogo from '../assets/images/yt-logo.png';

interface ImageItem {
  src: string;
  alt: string;
  id: string;
}

interface ImageLayout {
  id: string;
  x: number;
  y: number;
  width: number;
  height: number;
  zIndex: number;
}

const OutTheMusic: React.FC = () => {
  const [images, setImages] = useState<ImageItem[]>([]);
  const [layout, setLayout] = useState<ImageLayout[]>([]);
  const [isAnimating, setIsAnimating] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const animationRef = useRef<number | null>(null);

  // Todas las imágenes disponibles
  const availableImages: ImageItem[] = [
    { src: a1, alt: 'Imagen A1', id: 'a1' },
    { src: a2, alt: 'Imagen A2', id: 'a2' },
    { src: disc1, alt: 'Disco 1', id: 'disc1' },
    { src: disc2, alt: 'Disco 2', id: 'disc2' },
    { src: disc3, alt: 'Disco 3', id: 'disc3' },
    { src: disc4, alt: 'Disco 4', id: 'disc4' },
    { src: logoNeto, alt: 'Logo Neto', id: 'logo' },
    { src: ytLogo, alt: 'YouTube Logo', id: 'yt' }
  ];

  // Función para generar un layout dinámico
  const generateLayout = (images: ImageItem[], containerWidth: number, containerHeight: number): ImageLayout[] => {
    const layouts: ImageLayout[] = [];
    const numImages = Math.min(images.length, 9); // Máximo 9 imágenes
    const selectedImages = images.slice(0, numImages);
    
    // Determinar el patrón de layout
    const patterns = [
      // Patrón 1: Una imagen grande + 3 pequeñas
      () => {
        const large = selectedImages[0];
        const small = selectedImages.slice(1, 4);
        layouts.push({
          id: large.id,
          x: 0,
          y: 0,
          width: containerWidth * 0.6,
          height: containerHeight * 0.6,
          zIndex: 1
        });
        small.forEach((img, index) => {
          layouts.push({
            id: img.id,
            x: containerWidth * 0.6 + (index % 2) * (containerWidth * 0.4 / 2),
            y: (index < 2 ? 0 : containerHeight * 0.3) + (index % 2) * (containerHeight * 0.3),
            width: containerWidth * 0.4 / 2,
            height: containerHeight * 0.3,
            zIndex: 2
          });
        });
      },
      // Patrón 2: Grid 2x3
      () => {
        const cols = 2;
        const rows = 3;
        selectedImages.slice(0, 6).forEach((img, index) => {
          const col = index % cols;
          const row = Math.floor(index / cols);
          layouts.push({
            id: img.id,
            x: (containerWidth / cols) * col,
            y: (containerHeight / rows) * row,
            width: containerWidth / cols,
            height: containerHeight / rows,
            zIndex: 1
          });
        });
      },
      // Patrón 3: Una imagen central grande + 4 alrededor
      () => {
        const center = selectedImages[0];
        const around = selectedImages.slice(1, 5);
        layouts.push({
          id: center.id,
          x: containerWidth * 0.25,
          y: containerHeight * 0.25,
          width: containerWidth * 0.5,
          height: containerHeight * 0.5,
          zIndex: 2
        });
        around.forEach((img, index) => {
          const positions = [
            { x: 0, y: 0 }, // Esquina superior izquierda
            { x: containerWidth * 0.5, y: 0 }, // Esquina superior derecha
            { x: 0, y: containerHeight * 0.5 }, // Esquina inferior izquierda
            { x: containerWidth * 0.5, y: containerHeight * 0.5 } // Esquina inferior derecha
          ];
          const pos = positions[index];
          layouts.push({
            id: img.id,
            x: pos.x,
            y: pos.y,
            width: containerWidth * 0.25,
            height: containerHeight * 0.25,
            zIndex: 1
          });
        });
      }
    ];

    // Seleccionar un patrón aleatorio
    const pattern = patterns[Math.floor(Math.random() * patterns.length)];
    pattern();
    
    return layouts;
  };

  // Función para animar el cambio de layout
  const animateLayoutChange = () => {
    if (!containerRef.current || isAnimating) return;
    
    setIsAnimating(true);
    const container = containerRef.current;
    const containerWidth = container.offsetWidth;
    const containerHeight = container.offsetHeight;
    
    const newLayout = generateLayout(images, containerWidth, containerHeight);
    
    // Animar cada imagen a su nueva posición
    newLayout.forEach((newPos, index) => {
      const imgElement = document.getElementById(`img-${newPos.id}`);
      if (imgElement) {
        imgElement.style.transition = 'all 2s cubic-bezier(0.4, 0, 0.2, 1)';
        imgElement.style.transform = `translate(${newPos.x}px, ${newPos.y}px)`;
        imgElement.style.width = `${newPos.width}px`;
        imgElement.style.height = `${newPos.height}px`;
        imgElement.style.zIndex = newPos.zIndex.toString();
      }
    });
    
    setLayout(newLayout);
    
    // Resetear la animación después de completarse
    setTimeout(() => {
      setIsAnimating(false);
    }, 2000);
  };

  useEffect(() => {
    // Seleccionar 6-9 imágenes aleatorias
    const shuffledImages = [...availableImages].sort(() => Math.random() - 0.5);
    const selectedImages = shuffledImages.slice(0, Math.floor(Math.random() * 4) + 6); // Entre 6-9 imágenes
    setImages(selectedImages);
    
    // Generar layout inicial
    if (containerRef.current) {
      const container = containerRef.current;
      const containerWidth = container.offsetWidth;
      const containerHeight = container.offsetHeight;
      const initialLayout = generateLayout(selectedImages, containerWidth, containerHeight);
      setLayout(initialLayout);
    }
  }, []);

  useEffect(() => {
    // Cambiar layout cada 4-6 segundos
    const interval = setInterval(() => {
      animateLayoutChange();
    }, Math.random() * 2000 + 4000); // Entre 4-6 segundos

    return () => clearInterval(interval);
  }, [images, isAnimating]);

  // Manejar redimensionamiento de ventana
  useEffect(() => {
    const handleResize = () => {
      if (containerRef.current && !isAnimating) {
        const container = containerRef.current;
        const containerWidth = container.offsetWidth;
        const containerHeight = container.offsetHeight;
        const newLayout = generateLayout(images, containerWidth, containerHeight);
        setLayout(newLayout);
      }
    };

    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [images, isAnimating]);

  return (
    <div className="out-the-music">
      <div className="out-music-content">
        {/* Sección izquierda - Título y descripción */}
        <div className="out-music-text">
          <h1 className="out-music-title">Out The Music</h1>
          <p className="out-music-description">
            Una experiencia visual única donde las imágenes cobran vida, 
            reorganizándose constantemente en un ballet de formas y colores. 
            Cada momento es diferente, cada composición cuenta una historia.
          </p>
          <p className="out-music-description">
            Descubre la música visual que se esconde detrás de cada imagen, 
            donde el arte se mueve al ritmo de la creatividad.
          </p>
        </div>

        {/* Sección derecha - Galería dinámica */}
        <div className="out-music-gallery" ref={containerRef}>
          {layout.map((imgLayout, index) => {
            const image = images.find(img => img.id === imgLayout.id);
            if (!image) return null;
            
            return (
              <div
                key={`${imgLayout.id}-${index}`}
                id={`img-${imgLayout.id}`}
                className="out-music-image"
                style={{
                  position: 'absolute',
                  left: imgLayout.x,
                  top: imgLayout.y,
                  width: imgLayout.width,
                  height: imgLayout.height,
                  zIndex: imgLayout.zIndex,
                  transition: 'all 2s cubic-bezier(0.4, 0, 0.2, 1)'
                }}
              >
                <img
                  src={image.src}
                  alt={image.alt}
                  className="gallery-image"
                  onError={(e) => {
                    const target = e.target as HTMLImageElement;
                    target.style.display = 'none';
                    const noImageDiv = document.createElement('div');
                    noImageDiv.className = 'no-image-placeholder';
                    noImageDiv.textContent = 'No Image';
                    target.parentNode?.appendChild(noImageDiv);
                  }}
                />
                <div className="image-overlay">
                  <span className="image-title">{image.alt}</span>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default OutTheMusic;
